// Faithful port of CPython's difflib pieces needed for
// difflib.unified_diff(a, b, lineterm='') with default n=3,
// plus Python str.splitlines().

// Python str.splitlines() line boundaries:
// \n \r \r\n \v(\x0b) \f(\x0c) \x1c \x1d \x1e \x85(NEL) \u2028 \u2029
const BOUNDARY_CHARS = new Set([
  '\n', '\r', '\x0b', '\x0c', '\x1c', '\x1d', '\x1e', '\x85', '\u2028', '\u2029',
]);

export function splitLines(s) {
  const lines = [];
  const n = s.length;
  let start = 0;
  let i = 0;
  while (i < n) {
    const c = s[i];
    if (c === '\r') {
      lines.push(s.slice(start, i));
      i += 1;
      if (i < n && s[i] === '\n') i += 1; // \r\n is a single boundary
      start = i;
    } else if (BOUNDARY_CHARS.has(c)) {
      lines.push(s.slice(start, i));
      i += 1;
      start = i;
    } else {
      i += 1;
    }
  }
  if (start < n) lines.push(s.slice(start));
  return lines;
}

// Python's difflib._format_range_unified
function formatRangeUnified(start, stop) {
  let beginning = start + 1; // lines start numbering with one
  const length = stop - start;
  if (length === 1) return String(beginning);
  if (length === 0) beginning -= 1; // empty ranges begin at line just before the range
  return beginning + ',' + length;
}

// Faithful port of difflib.SequenceMatcher with isjunk=None, autojunk=True.
class SequenceMatcher {
  constructor(a, b) {
    this.a = a;
    this.b = b;
    this.autojunk = true;
    this.matchingBlocks = null;
    this.opcodes = null;
    this._chainB();
  }

  _chainB() {
    const b = this.b;
    const b2j = (this.b2j = new Map());
    for (let i = 0; i < b.length; i++) {
      const elt = b[i];
      let idxs = b2j.get(elt);
      if (idxs === undefined) {
        idxs = [];
        b2j.set(elt, idxs);
      }
      idxs.push(i);
    }

    // Purge junk elements (isjunk is None -> nothing is junk).
    this.bjunk = new Set();

    // Purge popular elements that are not junk.
    this.bpopular = new Set();
    const n = b.length;
    if (this.autojunk && n >= 200) {
      const ntest = Math.floor(n / 100) + 1;
      for (const [elt, idxs] of b2j) {
        if (idxs.length > ntest) {
          b2j.delete(elt);
          this.bpopular.add(elt);
        }
      }
    }
  }

  findLongestMatch(alo, ahi, blo, bhi) {
    const a = this.a;
    const b = this.b;
    const b2j = this.b2j;
    const bjunk = this.bjunk;

    let besti = alo;
    let bestj = blo;
    let bestsize = 0;

    // find longest junk-free match
    let j2len = new Map();
    for (let i = alo; i < ahi; i++) {
      const newj2len = new Map();
      const idxs = b2j.get(a[i]);
      if (idxs !== undefined) {
        for (const j of idxs) {
          // a[i] matches b[j]
          if (j < blo) continue;
          if (j >= bhi) break;
          const k = (j2len.get(j - 1) ?? 0) + 1;
          newj2len.set(j, k);
          if (k > bestsize) {
            besti = i - k + 1;
            bestj = j - k + 1;
            bestsize = k;
          }
        }
      }
      j2len = newj2len;
    }

    // Extend the best by non-junk elements on each end.
    while (
      besti > alo &&
      bestj > blo &&
      !bjunk.has(b[bestj - 1]) &&
      a[besti - 1] === b[bestj - 1]
    ) {
      besti -= 1;
      bestj -= 1;
      bestsize += 1;
    }
    while (
      besti + bestsize < ahi &&
      bestj + bestsize < bhi &&
      !bjunk.has(b[bestj + bestsize]) &&
      a[besti + bestsize] === b[bestj + bestsize]
    ) {
      bestsize += 1;
    }

    // Suck up matching junk on each side of the interesting match.
    while (
      besti > alo &&
      bestj > blo &&
      bjunk.has(b[bestj - 1]) &&
      a[besti - 1] === b[bestj - 1]
    ) {
      besti -= 1;
      bestj -= 1;
      bestsize += 1;
    }
    while (
      besti + bestsize < ahi &&
      bestj + bestsize < bhi &&
      bjunk.has(b[bestj + bestsize]) &&
      a[besti + bestsize] === b[bestj + bestsize]
    ) {
      bestsize += 1;
    }

    return [besti, bestj, bestsize];
  }

  getMatchingBlocks() {
    if (this.matchingBlocks !== null) return this.matchingBlocks;
    const la = this.a.length;
    const lb = this.b.length;

    // Queue-based iterative version of the recursive algorithm.
    const queue = [[0, la, 0, lb]];
    const matchingBlocks = [];
    while (queue.length > 0) {
      const [alo, ahi, blo, bhi] = queue.pop();
      const x = this.findLongestMatch(alo, ahi, blo, bhi);
      const [i, j, k] = x;
      // a[alo:i] vs b[blo:j] unknown
      // a[i:i+k] same as b[j:j+k]
      // a[i+k:ahi] vs b[j+k:bhi] unknown
      if (k !== 0) {
        matchingBlocks.push(x);
        if (alo < i && blo < j) queue.push([alo, i, blo, j]);
        if (i + k < ahi && j + k < bhi) queue.push([i + k, ahi, j + k, bhi]);
      }
    }
    matchingBlocks.sort((p, q) => p[0] - q[0] || p[1] - q[1]);

    // Collapse adjacent equal blocks into one.
    let i1 = 0;
    let j1 = 0;
    let k1 = 0;
    const nonAdjacent = [];
    for (const [i2, j2, k2] of matchingBlocks) {
      if (i1 + k1 === i2 && j1 + k1 === j2) {
        k1 += k2;
      } else {
        if (k1 !== 0) nonAdjacent.push([i1, j1, k1]);
        i1 = i2;
        j1 = j2;
        k1 = k2;
      }
    }
    if (k1 !== 0) nonAdjacent.push([i1, j1, k1]);

    nonAdjacent.push([la, lb, 0]); // sentinel
    this.matchingBlocks = nonAdjacent;
    return nonAdjacent;
  }

  getOpcodes() {
    if (this.opcodes !== null) return this.opcodes;
    let i = 0;
    let j = 0;
    const answer = [];
    for (const [ai, bj, size] of this.getMatchingBlocks()) {
      let tag = '';
      if (i < ai && j < bj) tag = 'replace';
      else if (i < ai) tag = 'delete';
      else if (j < bj) tag = 'insert';
      if (tag !== '') answer.push([tag, i, ai, j, bj]);
      i = ai + size;
      j = bj + size;
      // the list of matching blocks is terminated by a sentinel with size 0
      if (size !== 0) answer.push(['equal', ai, i, bj, j]);
    }
    this.opcodes = answer;
    return answer;
  }

  getGroupedOpcodes(n = 3) {
    if (n < 0) n = 0;
    let codes = this.getOpcodes();
    if (codes.length === 0) codes = [['equal', 0, 1, 0, 1]];
    // Fixup leading and trailing groups if they show no changes.
    if (codes[0][0] === 'equal') {
      const [tag, i1, i2, j1, j2] = codes[0];
      codes[0] = [tag, Math.max(i1, i2 - n), i2, Math.max(j1, j2 - n), j2];
    }
    if (codes[codes.length - 1][0] === 'equal') {
      const [tag, i1, i2, j1, j2] = codes[codes.length - 1];
      codes[codes.length - 1] = [tag, i1, Math.min(i2, i1 + n), j1, Math.min(j2, j1 + n)];
    }

    const nn = n + n;
    const groups = [];
    let group = [];
    for (const [tag, i1, i2, j1, j2] of codes) {
      // End the current group and start a new one whenever
      // there is a large range with no changes.
      if (tag === 'equal' && i2 - i1 > nn) {
        group.push([tag, i1, Math.min(i2, i1 + n), j1, Math.min(j2, j1 + n)]);
        groups.push(group);
        group = [[tag, Math.max(i1, i2 - n), i2, Math.max(j1, j2 - n), j2]];
        continue;
      }
      group.push([tag, i1, i2, j1, j2]);
    }
    if (group.length > 0 && !(group.length === 1 && group[0][0] === 'equal')) {
      groups.push(group);
    }
    return groups;
  }
}

// Port of difflib.unified_diff(a, b, lineterm='') with default n=3
// and empty file names/dates. Returns the list of yielded lines.
export function unifiedDiffLines(aLines, bLines) {
  const result = [];
  const matcher = new SequenceMatcher(aLines, bLines);
  let started = false;
  for (const group of matcher.getGroupedOpcodes(3)) {
    if (!started) {
      started = true;
      result.push('--- ');
      result.push('+++ ');
    }
    const first = group[0];
    const last = group[group.length - 1];
    const file1Range = formatRangeUnified(first[1], last[2]);
    const file2Range = formatRangeUnified(first[3], last[4]);
    result.push('@@ -' + file1Range + ' +' + file2Range + ' @@');

    for (const [tag, i1, i2, j1, j2] of group) {
      if (tag === 'equal') {
        for (let i = i1; i < i2; i++) result.push(' ' + aLines[i]);
        continue;
      }
      if (tag === 'replace' || tag === 'delete') {
        for (let i = i1; i < i2; i++) result.push('-' + aLines[i]);
      }
      if (tag === 'replace' || tag === 'insert') {
        for (let j = j1; j < j2; j++) result.push('+' + bLines[j]);
      }
    }
  }
  return result;
}

