// Exact reimplementation of Python 3's repr() for str.
// Reference: CPython unicode_repr (Objects/unicodeobject.c).
//
// Printability follows Python's str.isprintable(): a character is
// non-printable when its Unicode general category is one of
// Cc, Cf, Cs, Co, Cn (group C) or Zl, Zp, Zs (group Z),
// except U+0020 SPACE which is printable.
//
// The reference runtime uses Unicode 15.0 while this Node build ships
// Unicode 15.1; the only characters assigned in 15.1 that were unassigned
// (Cn) in 15.0 are CJK Extension I (U+2EBF0..U+2EE5D), so those are
// forced non-printable to match Unicode 15.0 exactly.

const NON_PRINTABLE = /[\p{C}\p{Z}]/u;

function isPrintable(cp) {
  if (cp === 0x20) return true; // U+0020 SPACE is printable
  if (cp >= 0x2ebf0 && cp <= 0x2ee5d) return false; // CJK Ext I: Cn in Unicode 15.0
  return !NON_PRINTABLE.test(String.fromCodePoint(cp));
}

function hexEscape(cp) {
  if (cp < 0x100) return "\\x" + cp.toString(16).padStart(2, "0");
  if (cp < 0x10000) return "\\u" + cp.toString(16).padStart(4, "0");
  return "\\U" + cp.toString(16).padStart(8, "0");
}

export function pyStrRepr(s) {
  // Quote selection: single quotes by default; if the string contains a
  // single quote but no double quote, use double quotes instead.
  let quote = "'";
