import { execFileSync } from "node:child_process";
import { pyStrRepr } from "/output/lib/pyrepr.mjs";

const EXE = "/workspace/dataset/test1_executable";

// Extract repr(a) from the executable's output line.
// Output: {'values_changed': {'root': {'new_value': R(b), 'old_value': R(a)[, 'diff': R(d)]}}}
function extractOldValueRepr(out) {
  const marker = "'old_value': ";
  const i = out.indexOf(marker);
  if (i < 0) throw new Error("no old_value in: " + JSON.stringify(out));
  let j = i + marker.length;
  const q = out[j];
  if (q !== "'" && q !== '"') throw new Error("bad quote in: " + JSON.stringify(out));
  let k = j + 1;
  while (k < out.length) {
    if (out[k] === "\\") { k += 2; continue; }
    if (out[k] === q) return out.slice(j, k + 1);
    k++;
  }
  throw new Error("unterminated repr in: " + JSON.stringify(out));
}

function groundTruth(a) {
  const out = execFileSync(EXE, ["--a", a, "--b", "ZZZ"], { encoding: "utf8" });
  return extractOldValueRepr(out);
}

const cases = [];
// quote selection
cases.push("plain", "it's", 'say "hi"', `both ' and "`, `''`, `""`, `'"`, `'`, `"`, `a'b"c`, "back\\slash", `\\'`, `\\"`);
// escapes and control chars
cases.push("a\nb", "a\rb", "a\tb", "\n", "\r", "\t", "\x07", "\x0b", "\x0c", "\x1b", "\x7f", "\x00\x01\x02", "end\x7f");
// boundaries of printability in Latin-1
cases.push(" ¡¢£", "­®¯", " ", " ", "");
// separators and format chars
cases.push("  ", " ", "​", "⁠", "﻿", "‪", "᠎", "́", " x");
// printable non-ASCII
cases.push("你好🌍", "🫠", "𞀰", "𑼀", "𱍐", "𐻽", "ÿþ", "αβγ", "日本語", "🎉🚀");
// Unicode 15.1 CJK Ext I (unassigned in 15.0)
cases.push("\u{2ebf0}", "\u{2ee5d}", "\u{2ebef}", "\u{2ee5e}", "a\u{2ec00}b");
// astral non-printables
cases.push("\u{e0001}", "\u{e000}\u{f8ff}", "\u{f0000}\u{ffffd}", "\u{100000}\u{10fffd}", "\u{e01ef}");
// specials: DEL region, C1 controls
cases.push("\x7f\x80\x9f", "", "");
// mixed long string
let mixed = "";
for (let i = 0; i < 400; i++) mixed += String.fromCodePoint((i * 37) % 0x500);
mixed += "你好🌍'\"\n\t\x07\x7f ​\u{2ebf0}\u{e0001}abc";
cases.push(mixed);
// full Latin-1 range sweep
let latin1 = "";
for (let cp = 0; cp < 0x100; cp++) latin1 += String.fromCodePoint(cp);
cases.push(latin1);
// BMP sweep in chunks (skip nothing; surrogates can't pass through argv safely, test separately)
for (let base = 0x100; base < 0x10000; base += 0x800) {
  let s = "";
  for (let cp = base; cp < base + 0x800; cp++) {
    if (cp >= 0xd800 && cp <= 0xdfff) continue;
    s += String.fromCodePoint(cp);
  }
  cases.push(s);
}
// astral sweep sampled
for (let base = 0x10000; base < 0x110000; base += 0x1000) {
  let s = "";
  for (let cp = base; cp < Math.min(base + 0x1000, 0x110000); cp += 7) s += String.fromCodePoint(cp);
  cases.push(s);
}

let pass = 0, fail = 0;
for (const a of cases) {
  let expected, actual;
  try { expected = groundTruth(a); } catch (e) { console.log("SKIP/err", JSON.stringify(a.slice(0,40)), e.message); continue; }
  try { actual = pyStrRepr(a); } catch (e) { console.log("THROW", JSON.stringify(a.slice(0,40)), e.message); fail++; continue; }
  if (expected === actual) pass++;
  else {
    fail++;
    console.log("FAIL input:", JSON.stringify(a.slice(0, 80)));
    console.log("  expected:", JSON.stringify(expected.slice(0, 200)));
    console.log("  actual  :", JSON.stringify(actual.slice(0, 200)));
  }
}
console.log(`\n${pass} passed, ${fail} failed, ${cases.length} total`);

