import { execFileSync } from 'node:child_process';
import { splitLines, unifiedDiffLines } from '/output/lib/difflib.mjs';

const EXE = '/workspace/dataset/test1_executable';

function runExe(a, b) {
  const out = execFileSync(EXE, ['--a', a, '--b', b], { encoding: 'utf8', maxBuffer: 1 << 26 });
  return out.endsWith('\n') ? out.slice(0, -1) : out;
}

// Parse one Python str repr literal starting at index i; returns [value, nextIndex]
function parseRepr(s, i) {
  const q = s[i];
  if (q !== "'" && q !== '"') throw new Error('bad repr at ' + i + ': ' + s.slice(i, i + 20));
  i++;
  let out = '';
  while (s[i] !== q) {
    if (s[i] === '\\') {
      const e = s[i + 1];
      if (e === 'x') { out += String.fromCodePoint(parseInt(s.slice(i + 2, i + 4), 16)); i += 4; continue; }
      if (e === 'u') { out += String.fromCodePoint(parseInt(s.slice(i + 2, i + 6), 16)); i += 6; continue; }
      if (e === 'U') { out += String.fromCodePoint(parseInt(s.slice(i + 2, i + 10), 16)); i += 10; continue; }
      const m = { n: '\n', r: '\r', t: '\t', a: '\x07', b: '\b', f: '\f', v: '\x0b', '\\': '\\', "'": "'", '"': '"', '0': '\0' };
      if (!(e in m)) throw new Error('unknown escape \\' + e);
      out += m[e]; i += 2; continue;
    }
    out += s[i]; i++;
  }
  return [out, i + 1];
}

// Returns { newValue, oldValue, diff (or null) } or null for '{}'
function parseOutput(line) {
  if (line === '{}') return null;
  const prefix = "{'values_changed': {'root': ";
  if (!line.startsWith(prefix) || !line.endsWith('}}}')) throw new Error('bad envelope: ' + line.slice(0, 60));
  let body = line.slice(prefix.length, -3);
  const pairs = {};
  let i = 0;
  while (i < body.length) {
    const [key, j1] = parseRepr(body, i);
    i = j1;
    if (body.slice(i, i + 2) !== ': ') throw new Error('bad kv sep');
    i += 2;
    const [val, j2] = parseRepr(body, i);
    i = j2;
    pairs[key] = val;
    if (i < body.length) {
      if (body.slice(i, i + 2) !== ', ') throw new Error('bad pair sep at ' + i);
      i += 2;
    }
  }
  return { newValue: pairs.new_value, oldValue: pairs.old_value, diff: 'diff' in pairs ? pairs.diff : null };
}

let pass = 0, fail = 0;
const failures = [];
function check(name, a, b) {
  const line = runExe(a, b);
  const parsed = parseOutput(line);
  const mine = unifiedDiffLines(splitLines(a), splitLines(b));
  const mineText = mine.join('\n');
  let expected;
  if (parsed === null) {
    expected = null; // equal -> empty diff
  } else {
    expected = parsed.diff; // may be null (no diff key) -> diff must be empty
  }
  const expectDiffText = expected === null ? '' : expected;
  const ok = mineText === expectDiffText;
  if (ok) { pass++; }
  else {
    fail++;
    failures.push({ name, a: JSON.stringify(a).slice(0, 120), b: JSON.stringify(b).slice(0, 120), expected: JSON.stringify(expectDiffText).slice(0, 300), got: JSON.stringify(mineText).slice(0, 300) });
  }
}

// ---- targeted cases ----
check('equal', 'x', 'x');
check('trailing-nl-equal', 'x', 'x\n');
check('no-nl-change', 'a\rb', 'a\rc');
check('spec1', 'line1\nline2', 'tab\there');
check('spec2', 'a\nb', 'a\nc');
check('insert-one', 'a\nb', 'a\nx\nb');
check('delete-one', 'a\nx\nb', 'a\nb');
check('change-first', 'a\nb\nc', 'z\nb\nc');
check('change-last', 'a\nb\nc', 'a\nb\nz');
check('empty-vs-lines', '', 'a\nb');
check('lines-vs-empty', 'a\nb', '');
check('adjacent-changes', 'a\nb\nc\nd\ne', 'a\nB\nc\nD\ne');
check('far-apart-multihunk',
  Array.from({ length: 30 }, (_, i) => 'line' + (i + 1)).join('\n'),
  Array.from({ length: 30 }, (_, i) => (i === 4 || i === 24 ? 'X' + i : 'line' + (i + 1))).join('\n'));
// 50 vs 49 + x change at end (spec example 3)
check('spec3',
  Array.from({ length: 50 }, (_, i) => 'line' + (i + 1)).join('\n'),
  Array.from({ length: 49 }, (_, i) => (i === 48 ? 'line49x' : 'line' + (i + 1))).join('\n'));
// context merging boundary at n=3: changes exactly 7 lines apart merge (>6 splits)
{
  const a = [], b = [];
  for (let i = 0; i < 12; i++) { a.push('L' + i); b.push('L' + i); }
  b[1] = 'X'; b[8] = 'Y'; // equal gap of 6 -> merge into one hunk
  check('merge-gap6', a.join('\n'), b.join('\n'));
  const a2 = a.slice(), b2 = b.slice();
  b2[1] = 'X'; b2[9] = 'Y'; // gap of 7 -> two hunks
  check('split-gap7', a2.join('\n'), b2.join('\n'));
}
// exotic line boundaries mixed with \n
check('vtab-boundary', 'a\x0bb\nc', 'a\x0bx\nc');
check('cr-boundary', 'a\rb\nc\nd', 'a\rx\nc\nd');
check('crlf-boundary', 'a\r\nb\nc', 'a\r\nx\nc');
check('file-sep', 'a\x1cb\n\x1dc\nd', 'a\x1cb\n\x1dX\nd');
check('nel-ls-ps', 'a\x85b\n\u2028c\u2029d', 'a\x85b\n\u2028X\u2029d');
check('blank-lines', 'a\n\n\nb', 'a\n\nx\n\nb');
check('only-newlines', '\n\n\n', '\n\n');
check('trailing-newline-diff', 'a\nb\n', 'a\nb\nc\n');
check('swap-lines', 'a\nb\nc\nd', 'c\nd\na\nb');
check('repeated-small', 'a\nb\na\nb\na\nb', 'b\na\nb\na\nb\na');
// autojunk: b has >=200 lines, 'spam' appears often (> ntest = n//100+1)
{
  const a = [], b = [];
  for (let i = 0; i < 250; i++) { a.push(i % 2 ? 'spam' : 'egg' + i); b.push(i % 2 ? 'spam' : 'egg' + i); }
  b[100] = 'CHANGED'; b.splice(150, 0, 'INSERTED');
  check('autojunk-250', a.join('\n'), b.join('\n'));
  const a2 = [], b2 = [];
  for (let i = 0; i < 250; i++) { a2.push('spam'); b2.push('spam'); }
  a2.push('end-a'); b2.push('end-b');
  check('autojunk-all-same', a2.join('\n'), b2.join('\n'));
  // below the 200 threshold: no autojunk
  const a3 = [], b3 = [];
  for (let i = 0; i < 199; i++) { a3.push('spam'); b3.push('spam'); }
  a3.push('a-tail'); b3.push('b-tail');
  check('no-autojunk-199', a3.join('\n'), b3.join('\n'));
  // long identical prefix/suffix with many repeats
  const a4 = [], b4 = [];
  for (let i = 0; i < 300; i++) { a4.push('x' + (i % 10)); b4.push('x' + (i % 10)); }
  b4[77] = 'odd'; a4.splice(200, 0, 'only-in-a');
  check('autojunk-300-cycle', a4.join('\n'), b4.join('\n'));
}
// unicode content in lines
check('unicode-lines', '你好\n世界\n🌍', '你好\n世X\n🌍');
check('quotes-in-lines', "it's\n\"q\"\nback\\slash", "it's\n\"q\"\nback/slash");

// ---- fuzz ----
function rng(seed) {
  let s = seed >>> 0;
  return () => { s = (s * 1103515245 + 12345) & 0x7fffffff; return s / 0x7fffffff; };
}
function fuzzBatch(seed, count, alpha, maxLines, maxLineLen) {
  const rand = rng(seed);
  for (let t = 0; t < count; t++) {
    const mk = () => {
      const nl = 1 + Math.floor(rand() * maxLines);
      const parts = [];
      for (let i = 0; i < nl; i++) {
        const ll = Math.floor(rand() * maxLineLen);
        let line = '';
        for (let j = 0; j < ll; j++) line += alpha[Math.floor(rand() * alpha.length)];
        parts.push(line);
      }
      return parts.join('\n');
    };
    let a = mk(), b = mk();
    // half the time derive b from a with small edits to get realistic diffs
    if (rand() < 0.5) {
      const lines = a.split('\n');
      for (let e = 0; e < 3; e++) {
        if (lines.length === 0) break;
        const op = rand();
        const idx = Math.floor(rand() * lines.length);
        if (op < 0.4) lines[idx] = lines[idx] + 'x';
        else if (op < 0.7) lines.splice(idx, 0, 'new' + Math.floor(rand() * 3));
        else lines.splice(idx, 1);
      }
      b = lines.join('\n');
    }
    check('fuzz-' + seed + '-' + t, a, b);
  }
}

fuzzBatch(1, 150, ['a', 'b', 'c'], 8, 6);
fuzzBatch(2, 100, ['a', 'b', 'c', 'd', 'e'], 20, 10);
fuzzBatch(3, 60, ['x', 'y', '\r', '\x0b', '\x1c'], 12, 5); // exotic boundaries mixed with \n joins
// fuzz with big inputs to hit autojunk
{
  const rand = rng(4);
  for (let t = 0; t < 25; t++) {
    const n = 200 + Math.floor(rand() * 150);
    const a = [], b = [];
    for (let i = 0; i < n; i++) {
      const v = 'L' + Math.floor(rand() * 5);
      a.push(v); b.push(v);
    }
    for (let e = 0; e < 5; e++) {
      const idx = Math.floor(rand() * b.length);
      const op = rand();
      if (op < 0.4) b[idx] = 'M' + Math.floor(rand() * 5);
      else if (op < 0.7) b.splice(idx, 0, 'N');
      else b.splice(idx, 1);
    }
    check('fuzz-big-' + t, a.join('\n'), b.join('\n'));
  }
}

console.log(`PASS: ${pass}, FAIL: ${fail}`);
for (const f of failures.slice(0, 10)) {
  console.log('FAIL', f.name);
  console.log('  a:', f.a);
  console.log('  b:', f.b);
  console.log('  expected:', f.expected);
  console.log('  got:     ', f.got);
}
process.exit(fail ? 1 : 0);

