    } else if (s === '--') {
      seenDoubleDash = true;
      argPattern.push('-');
    } else {
      const tuple = parseOptional(s);
      if (tuple) {
        argPattern.push('O');
        optionIndices.set(i, tuple);
      } else {
        argPattern.push('A');
      }
    }
