import { spawnSync } from 'node:child_process';

const EXE = '/workspace/dataset/test1_executable';

function runExe(args) {
  const r = spawnSync(EXE, args, { encoding: 'buffer', maxBuffer: 64 * 1024 * 1024 });
  return { code: r.status, out: r.stdout, err: r.stderr };
}
function runNode(args) {
  const r = spawnSync('node', ['/tmp/runner.mjs', ...args], { encoding: 'buffer', maxBuffer: 64 * 1024 * 1024 });
  return { code: r.status, out: r.stdout, err: r.stderr };
}

// Extract a,b from the executable's success output (values restricted to
// chars whose Python repr is plain single-quoted).
function extractAB(out) {
  const s = out.toString('utf8');
  if (s === '{}\n') return { a: null, b: null, equal: true };
  const m = s.match(/^\{'values_changed': \{'root': \{'new_value': '(.*)', 'old_value': '(.*)'\}\}\}\n$/);
  if (!m) return { parseError: s };
  return { a: m[2], b: m[1] };
}

const cases = [
  [], ['-h'], ['--help'], ['--he'], ['--h'],
  ['--a', 'x', '--b', 'y'],
  ['--b', 'y', '--a', 'x'],
  ['--a=x', '--b=y'],
  ['--a', 'x', '--a', 'y', '--b', 'z'],
  ['--a', '-5', '--b', '-3.2'],
  ['--a', '-.5', '--b', '2'],
  ['--a', '-5.', '--b', '2'],
  ['--a', '-', '--b', '2'],
  ['--a', '-5x', '--b', '2'],
  ['--a=-x', '--b=2'],
  ['--a=-5', '--b=-3.2'],
  ['--a', '-x'],
  ['--a', '-h'],
  ['--a', '--b', '2'],
  ['--a', '--', '-5', '--b', 'y'],
  ['--a', 'x', '--b'],
  ['--a', '--help', '--b', '2'],
  ['--a'], ['--b'],
  ['--a', '1'],
  ['--b', '2'],
  ['--a', '1', '--b', '2', '--extra', 'z'],
  ['--a', '1', '--b', '2', 'pos1', 'pos2'],
  ['x', '--a', '1', '--b', '2'],
  ['--a', '1', 'pos', '--b', '2'],
  ['--a', '1', '--b', '2', '--bad=foo'],
  ['--a', '1', '--b', '2', '--bad1', 'x', '--bad2'],
  ['--a', '1', '--b', '2', '-x'],
  ['-x', '--a', '1', '--b', '2'],
  ['--a', '1', '--b', '2', '-x', 'foo'],
  ['-xh', '--a', '1', '--b', '2'],
  ['--A', '1', '--b', '2'],
  ['--a', '1', '--b', '2', '--'],
  ['--a', '1', '--b', '2', '--', 'foo'],
  ['--a', '1', '--b', '2', '--', '--a', 'w'],
  ['--', '--a', '1', '--b', '2'],
  ['--a', '1', '--', '--b', '2'],
  ['--a', '1', '--b', '2', '--', '-h'],
  ['--a', '1', '--b', '2', '--', '--'],
  ['--=x', '--a', '1', '--b', '2'],
  ['--a=', '--b='],
  ['--a', '1', '--b', '2', '-h'],
  ['-h', '--a'],
  ['--bad', '-h'],
  ['-hx'], ['-hh'], ['-h=x'], ['-h='],
  ['--he=x'], ['--help=x'], ['--help='],
  ['--he=a b'],
  ["--he=a'b"],
  ['--he=a"b'],
  ["--he=a'\"b"],
  ['--he=\\'],
  ['--he=x\ty'],
  ['--a', ' ', '--b', ' x '],
  ['--a', '', '--b', ''],
  ['--a', 'a b', '--b', 'c'],
  ['-'],
  ['--a', '1', '--b', '2', '-'],
  ['-=x'],
  ['-5'],
  ['--a', '1', '--b', '2', '-5'],
  ['--a', '1', '--a'],
  ['--b', '2', '--a'],
  ['--a1', '--b', '2'],
  ['--aa', '--b', '2'],
  ['--b=y', '--a=x', '--b=w'],
  ['--a', '-0.5', '--b', '-0'],
  ['--a', '-5e3', '--b', '2'],
  ['--a', '--5', '--b', '2'],
  ['--a', '1', '--b', '2', '-- '],
  [' --a', '1', '--b', '2'],
  ['--a', '1', '--b', '2', '--a '],
];

let pass = 0, fail = 0;
for (const args of cases) {
  const e = runExe(args);
  const n = runNode(args);
  let ok = true;
  const problems = [];
  if (e.code !== n.code) { ok = false; problems.push(`exit ${e.code} != ${n.code}`); }
  if (!e.err.equals(n.err)) { ok = false; problems.push(`stderr differs: exe=${JSON.stringify(e.err.toString())} node=${JSON.stringify(n.err.toString())}`); }
  if (e.code === 0) {
    const eo = e.out.toString();
    if (eo.startsWith('usage:')) {
      if (!e.out.equals(n.out)) { ok = false; problems.push(`help stdout differs: exe=${JSON.stringify(eo)} node=${JSON.stringify(n.out.toString())}`); }
    } else {
      const ab = extractAB(e.out);
      const m = n.out.toString().match(/^RESULT (.*)\n$/);
      if (!m) { ok = false; problems.push(`node stdout bad: ${JSON.stringify(n.out.toString())}`); }
      else {
        const got = JSON.parse(m[1]);
        if (ab.parseError) { ok = false; problems.push(`cannot parse exe output: ${JSON.stringify(ab.parseError)}`); }
        else if (ab.equal) { if (got.a !== got.b) { ok = false; problems.push(`exe says a==b, node got ${JSON.stringify(got)}`); } }
        else if (got.a !== ab.a || got.b !== ab.b) { ok = false; problems.push(`exe a=${JSON.stringify(ab.a)} b=${JSON.stringify(ab.b)}, node ${JSON.stringify(got)}`); }
      }
    }
  } else {
    // error/help paths write nothing to stdout on error
    if (e.code === 2 && n.out.length !== 0) { ok = false; problems.push(`node wrote stdout on error: ${JSON.stringify(n.out.toString())}`); }
  }
  if (ok) pass++;
  else {
    fail++;
    console.log(`FAIL ${JSON.stringify(args)}: ${problems.join('; ')}`);
  }
}
console.log(`\n${pass} passed, ${fail} failed out of ${cases.length}`);
process.exit(fail ? 1 : 0);

