import { execFile } from "node:child_process";
import { promisify } from "node:util";
import { pyStrRepr } from "/output/lib/pyrepr.mjs";
const execFileP = promisify(execFile);
const EXE = "/workspace/dataset/test1_executable";

function extractOldValueRepr(out) {
  const marker = "'old_value': ";
  const i = out.indexOf(marker);
  let j = i + marker.length;
  const q = out[j];
  let k = j + 1;
  while (k < out.length) {
    if (out[k] === "\\") { k += 2; continue; }
    if (out[k] === q) return out.slice(j, k + 1);
    k++;
  }
  throw new Error("unterminated");
}

async function gt(a) {
  const { stdout } = await execFileP(EXE, ["--a", a, "--b", "ZZZ"], { encoding: "utf8", maxBuffer: 64 * 1024 * 1024 });
  return extractOldValueRepr(stdout);
}

const ranges = [];
for (let cp = 0x2900; cp < 0x3100; cp++) ranges.push(cp);
for (let cp = 0x3100; cp < 0x3900; cp++) ranges.push(cp);

let idx = 0, diffs = [];
async function worker() {
  while (idx < ranges.length) {
    const cp = ranges[idx++];
    const ch = String.fromCodePoint(cp);
    const e = await gt(ch);
    const a = pyStrRepr(ch);
    if (e !== a) diffs.push([cp.toString(16), e, a]);
  }
}
await Promise.all(Array.from({ length: 8 }, worker));
for (const d of diffs) console.log(d.join("  |  "));
console.log("total diffs:", diffs.length);

