import { spawnSync } from 'node:child_process';

const EXE = '/workspace/dataset/test1_executable';
function run(cmd, args) {
  const r = spawnSync(cmd, args, { encoding: 'buffer', maxBuffer: 64 * 1024 * 1024 });
  return { code: r.status, out: r.stdout, err: r.stderr };
}

const tokens = [
  '--a', '--b', '-h', '--help', '--he', '--h', '--', '-', '-x', '--x',
  '--a=v1', '--b=v2', '--he=x', '-hh', '-hx', '-h=x', '--=y', '-=z',
  '-5', '-3.2', '-.5', '-5.', 'v', 'w', '', 'p q', '--bad', '--bad=k',
  '--a=', '--b=', '-0', '--aa', '--bb', '--a1',
];

// deterministic PRNG
let seed = 12345;
function rnd(n) { seed = (seed * 1103515245 + 12345) & 0x7fffffff; return seed % n; }

let pass = 0, fail = 0;
const N = 600;
for (let t = 0; t < N; t++) {
  const len = rnd(6);
  const args = [];
  for (let i = 0; i < len; i++) args.push(tokens[rnd(tokens.length)]);
  const e = run(EXE, args);
  const n = run('node', ['/tmp/runner.mjs', ...args]);
  let ok = e.code === n.code && e.err.equals(n.err);
  if (ok && e.code === 0) {
    if (e.out.toString().startsWith('usage:')) {
      ok = e.out.equals(n.out);
    } else {
      // success: parse values from both
      const eo = e.out.toString();
      const m = n.out.toString().match(/^RESULT (.*)\n$/);
      if (!m) ok = false;
      else {
        const got = JSON.parse(m[1]);
        if (eo === '{}\n') ok = got.a === got.b;
        else {
          const mm = eo.match(/^\{'values_changed': \{'root': \{'new_value': '(.*)', 'old_value': '(.*)'\}\}\}\n$/);
          ok = !!mm && mm[2] === got.a && mm[1] === got.b;
        }
      }
    }
  }
  if (ok) pass++;
  else {
    fail++;
    if (fail <= 10) {
      console.log(`FAIL ${JSON.stringify(args)}`);
      console.log(`  exe:  code=${e.code} out=${JSON.stringify(e.out.toString())} err=${JSON.stringify(e.err.toString())}`);
      console.log(`  node: code=${n.code} out=${JSON.stringify(n.out.toString())} err=${JSON.stringify(n.err.toString())}`);
    }
  }
}
console.log(`\nfuzz: ${pass} passed, ${fail} failed out of ${N}`);
process.exit(fail ? 1 : 0);

